code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    def segments(n, is_sep):
        parts = []
        start = 0
        for i in range(n):
            if is_sep(i):
                if start < i:
                    parts.append(list(range(start, i)))
                start = i + 1
        if start < n:
            parts.append(list(range(start, n)))
        return parts
    row_parts = segments(h, lambda r: all(v == 8 for v in grid[r]))
    col_parts = segments(w, lambda c: all(grid[r][c] == 8 for r in range(h)))
    from collections import Counter
    nr = Counter(map(len, row_parts)).most_common(1)[0][0]
    nc = Counter(map(len, col_parts)).most_common(1)[0][0]
    row_parts = [p for p in row_parts if len(p) == nr]
    col_parts = [p for p in col_parts if len(p) == nc]
    markers = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0, 8):
                pr = next((i for i, part in enumerate(row_parts) if r in part), None)
                pc = next((i for i, part in enumerate(col_parts) if c in part), None)
                if pr is not None and pc is not None:
                    markers.setdefault(grid[r][c], set()).add((pr, pc))
    lines = {color: set() for color in markers}
    for color, points in markers.items():
        for r in {r for r, c in points}:
            cols = sorted(c for rr, c in points if rr == r)
            for a_i in range(len(cols)):
                for b_i in range(a_i + 1, len(cols)):
                    a, b = cols[a_i], cols[b_i]
                    lines[color].update((r, c) for c in range(a, min(len(col_parts), 2*b-a+1)))
        for c in {c for r, c in points}:
            rows = sorted(r for r, cc in points if cc == c)
            for a_i in range(len(rows)):
                for b_i in range(a_i + 1, len(rows)):
                    a, b = rows[a_i], rows[b_i]
                    lines[color].update((r, c) for r in range(a, min(len(row_parts), 2*b-a+1)))
    out = [row[:] for row in grid]
    for pr, rp in enumerate(row_parts):
        for pc, cp in enumerate(col_parts):
            colors = [color for color in lines if (pr, pc) in lines[color]]
            if colors:
                value = 6 if len(colors) > 1 else colors[0]
                for r in rp:
                    for c in cp:
                        out[r][c] = value
    return out
'''
